SELECT 

FROM project p
LEFT JOIN employee e ON p.leader_id = e.id AND e.delflag = 0

    p.delflag = 0

        AND p.name LIKE CONCAT('%', #{params.name}, '%')


        AND p.category = #{params.category}


        AND p.status = #{params.status}


        AND p.leader_id = #{params.leaderId}


        AND p.customer_name LIKE CONCAT('%', #{params.customerName}, '%')


        AND p.start_time >= #{params.startTimeStart}


        AND p.start_time <= #{params.startTimeEnd}


        AND p.final_status = #{params.finalStatus}




        ORDER BY ${params.sortField} ${params.sortOrder}


        ORDER BY p.created_at DESC

